unit Alternatives;

interface

function Repeated(Op: Integer): Integer;
function Pick(Lookup: Pointer): Integer;

implementation

function Repeated(Op: Integer): Integer;
begin
  Result := 0;
  case Op of
    1:
      {$IFDEF UNICODE}
      begin
        CountWide(Result);
      end;
      {$ELSE}
      while Result < 10 do
        CountAnsi(Result);
      {$ENDIF}
    2:
      Result := 2;
  end;
end;

function Pick(Lookup: Pointer): Integer;
begin
  if Lookup = nil then
    {$IFDEF ASMX86}
    Result := PosAsm(0)
    {$ELSE}
    Result := PosPas(0)
    {$ENDIF}
  else
    Result := PosLookup(Lookup);
end;

end.

